#include "../RWDiscoveryPolicy.h"
#include "../RWByteRange.h"
#include "../RWTransferWindow.h"
#include <cstdio>
int main(){int checks=0,failures=0;
auto check=[&](bool pass,const char *message){checks++;if(!pass){failures++;std::fprintf(stderr,"FAIL: %s\n",message);}};
check(!RWProbeExpired(13,false,0,13),"Give initial peer discovery its bounded window");
check(RWProbeExpired(14,false,0,14),"Dead source rotates without a 75 second wait");
check(!RWProbeExpired(16,false,3,16),"Connected peers have time to exchange metadata");
check(RWProbeExpired(22,false,3,22),"Non-responsive connected peers cannot stall indefinitely");
check(!RWProbeExpired(30,true,2,1),"Actively downloading source is not killed by no-peer deadline");
check(RWProbeExpired(30,true,2,12),"Metadata alone is insufficient if payload stops");
check(RWProbeExpired(40,true,10,0),"Probe has an absolute budget even with trickle traffic");
check(RWReadinessScore(false,false,0,500000,100000,1000)<0,"Unverified startup bytes can never win");
check(RWReadinessScore(true,false,0,200000,100000,0)>RWReadinessScore(true,false,3,2000000,500000,1000000),"Playable buffer wins over a faster candidate that still needs more startup data");
check(RWReadinessScore(true,true,0,0,100000,0)>RWReadinessScore(true,false,0,2000000,100000,1000),"Complete verified file wins offline without a new transfer");
check(RWReadinessScore(false,true,0,0,0,0)<0,"Completion cannot bypass verified header readiness");
check(RWReadinessScore(true,false,0,0,100000,1000000)<0,"Ranking hints cannot substitute for live transfer");
check(RWReadinessScore(true,false,NAN,200000,100000,0)<0,"Invalid ETA cannot enter ranking");
check(RWStartupTransferETA(8*1024*1024,0,100000,1024*1024)==8,"Opening ETA includes the full missing torrent piece");
check(RWStartupTransferETA(0,8*1024*1024,100000,1024*1024)==0,"Verified useful opening data does not need downloading again");
check(RWStartupTransferETA(0,100000,100000,200000)==1,"Small opening accounts for a short buffer at the media bitrate");
check(RWStartupTransferETA(100,0,100000,0)<0,"No delivery speed remains an unknown ETA");
RWTransferWindow steady;steady.observe(0,0);
for(int i=1;i<=6;i++)steady.observe(i,i*100000);
check(steady.observe(7,700000)==100000&&steady.measuredSeconds()==7,"Steady payload produces its sustained rate");
RWTransferWindow delayed;for(int i=0;i<=15;i++)delayed.observe(i,0);
delayed.observe(16,100000);check(delayed.observe(17,200000)==100000&&delayed.measuredSeconds()==2,"Peer discovery delay is separate from transfer throughput");
RWTransferWindow burst;burst.observe(0,0);burst.observe(1,1000000);
check(burst.observe(2,1000000)<1000000,"One burst decays instead of remaining a peak-speed estimate");
burst.observe(3,1000000);check(burst.observe(4,1000000)==0,"A stopped transfer cannot remain healthy from old payload");
check(steady.observe(8,0)==0&&steady.measuredSeconds()==0,"Reset payload counters start a new measurement");
check(delayed.observe(30,300000)==0&&delayed.measuredSeconds()==0,"Long suspension requires a fresh throughput window");
check(delayed.observe(NAN,0)==0,"Invalid sample clocks are ignored");
check(RWProbeHeadBytes(2ULL*1024*1024*1024)==65536,"Opening test does not wait for 512 KiB before preparing media");
check(RWProbeHeadBytes(100)==100,"Small files require only their available header");
check(RWProbeMeasurementPiece(0,20,true,[](int p){return p<2;})==2,"Cached opening requests one missing piece to measure today's connection");
check(RWProbeMeasurementPiece(0,20,false,[](int p){return p<2;})==-1,"Cold opening remains the only probe until it is verified");
check(RWProbeMeasurementPiece(0,20,true,[](int){return true;})==-1,"A complete offline video needs no measurement download");
check(RWProbeMeasurementPiece(22,30,true,[](int p){return p==22;})==23,"Measurement stays inside the selected episode, not another pack file");
int64_t first=0,last=0;
check(RWPieceRange(0,1000000,0,RWProbeHeadBytes(1000000),262144,&first,&last)&&first==0&&last==0,"Aligned 256 KiB torrent starts after one verified piece");
check(RWPieceRange(262144-100,1000000,0,RWProbeHeadBytes(1000000),262144,&first,&last)&&first==0&&last==1,"Unaligned file verifies both pieces needed for its header");
check(RWProbeDeadline(0,2)<RWProbeDeadline(1,2)&&RWProbeDeadline(1,2)<RWProbeDeadline(2,2),"Opening pieces precede speculative metadata tail requests");
check(RWProbeDeadline(2,2)<RWProbeDeadline(3,2),"Tail pieces keep deterministic download order");
check(RWMaxTorrentPieceBytes>=8388608&&RWVerifiedPieceCacheBytes>=RWMaxTorrentPieceBytes,"Verified 8 MiB series-pack pieces fit the bounded reader");
check(RWPieceRange(175,175686637,0,65536,8388608,&first,&last)&&first==0&&last==0,"Real S01E01 starts inside the pack's first 8 MiB piece");
check(RWPieceRange(40LL*1024*1024*1024,175686637,175686637-65536,65536,8388608,&first,&last)&&first>4096,"Later pack episodes retain 64-bit offsets");
double required=RWRequiredStreamRate(175686637,25*60);
check(required>117000&&required<118000,"Bitrate estimate uses the 176 MB episode, not the 47 GB series pack");
check(RWRequiredStreamRate(175686637,0)==0,"Missing runtime remains unknown, not a fabricated bitrate");
check(!RWStreamingReady(true,false,2,9000,required,10),"Connected source at 9 KB/s cannot be labelled ready for this episode");
check(!RWStreamingReady(true,false,2,200000,required,3,2000000),"Short marginal sample cannot qualify even with cached data ahead");
check(RWStreamingReady(true,false,2,200000,required,6,2000000),"Sustained measured transfer with a verified reserve can stream");
check(!RWStreamingReady(true,false,20,1000000,required,.1),"A momentary burst or seed count cannot skip the measurement window");
check(!RWStreamingReady(true,false,0,200000,required,3),"Disconnected cached opening cannot win with stale transfer stats");
check(RWStreamingReady(true,true,0,0,required,0),"Complete verified download needs no network throughput");
check(RWProbeTooSlow(10,9000,required,8*1024*1024),"Measured slow source rotates without waiting 40 seconds");
check(!RWProbeTooSlow(2,9000,required,8*1024*1024),"Ramp-up is measured before rejecting low speed");
check(!RWProbeTooSlow(10,500000,required,8*1024*1024),"Healthy 8 MiB piece can finish within its opening budget");
check(RWProbeTooSlow(10,9000,0,1024*1024),"Opening-piece ETA detects a slow source even without runtime metadata");
// The physical 0.20 failure: a useful 215 KB/s source was killed at 40 seconds
// with 3.2 MB of its 8 MiB opening received. It needed about 24 more seconds.
bool finish=RWCanFinishOpening(14,214855.747,required,8388608-3222943,59,0);
check(finish,"Reported healthy source has enough remaining budget to finish");
check(!RWProbeExpired(40.447,true,2,0,finish),"Reported 0.20 transfer survives the old 40-second cutoff");
check(!RWProbeTooSlow(14,214855.747,required,8388608-3222943,59),"Real source is not rejected using the obsolete 30-second ETA limit");
check(!RWCanFinishOpening(14,214855,required,8388608-3222943,20,0),"Extension is denied if the remaining session cannot finish the opening");
check(!RWCanFinishOpening(14,9000,required,8388608-3222943,59,0),"Trickle traffic cannot buy an extended opening window");
check(!RWCanFinishOpening(14,214855,required,8388608-3222943,59,4),"A stopped connection cannot use its old average to extend the deadline");
check(RWProbeExpired(100,true,2,0,true),"Healthy transfer cannot exceed the hard discovery limit");
check(RWProbeExpired(45,true,0,13,true),"An idle source still expires even if its old ETA looked good");
check(!RWLocalCheckExpired(45.453,0,54),"Reported 92-percent-complete check is not killed at the old 45-second cutoff");
check(RWLocalCheckExpired(45,12,54),"A stuck local check still expires");
check(RWLocalCheckExpired(100,0,0),"A progressing local check remains inside the global discovery deadline");
check(!RWProbeExpired(2,true,0,2),"Finishing a long check leaves a fresh network discovery window");
check(RWProbeAheadPiece(0,0,35,false,[](int){return false;})==1,"Cold probe leaves another piece wanted when its opening completes");
check(RWProbeAheadPiece(22,23,40,false,[](int){return false;})==24,"Lookahead follows every header piece when the file crosses a boundary");
check(RWProbeAheadPiece(22,23,40,true,[](int p){return p<=25;})==26,"Cached header measures the first missing video piece");
check(RWProbeAheadPiece(22,23,23,false,[](int){return false;})==-1,"Lookahead cannot request the next episode");
check(!RWProbeExpired(17,true,1,4),"A first peer at 13 seconds gets time to deliver data despite cached metadata");
check(RWProbeDemandTarget(400000)>=400000*12,"Probe can queue the verified reserve needed to qualify a fast peer without waiting for a refill");
check(RWProbeDemandTarget(900*1024)==8*1024*1024,"High bitrate reserve requests remain capped even when twelve seconds exceeds the target window");
check(RWProbeDemandTarget(0)==2*1024*1024&&RWProbeDemandTarget(NAN)==2*1024*1024,"Unknown runtime has a bounded useful measurement window");
check(RWProbeDemandTarget(10*1024*1024)==8*1024*1024,"Large bitrate cannot create an unbounded outstanding probe");
check(RWProbeMayExtend(2*1024*1024,0,1024*1024,900*1024),"Completed tiny probe is replenished for a real throughput sample");
check(!RWProbeMayExtend(RWProbeTransferBudget,0,1024*1024,900*1024),"Per-candidate request budget cannot be exceeded");
check(!RWProbeMayExtend(24*1024*1024,0,16*1024*1024,900*1024),"Whole-piece cost must fit the remaining budget");
check(!RWProbeMayExtend(8*1024*1024,8*1024*1024,1024*1024,900*1024),"Enough pending data prevents extra requests");
std::printf("{\"checks\":%d,\"failures\":%d}\n",checks,failures);return failures?1:0;
}
